Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Translation composition</span>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;line-height:1.35;max-width:260px"></span>
<span style="display:flex;align-items:center;gap:6px"><button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button></span>
<span style="display:flex;gap:4px;flex-wrap:wrap"><button id="stageSingleBtn" onclick="setCompositionStage('single')">single</button><button id="stageChainedBtn" onclick="setCompositionStage('chained')">chained</button><button id="stageComposedBtn" onclick="setCompositionStage('composed')">composed</button></span>
<span style="font-size:10px;line-height:1.35;color:#333">Drag the red arrowheads to change <i>t</i> and, in chained/composed mode, <i>s</i>.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 900, H = 620;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var ORANGE = '#ff8000';
var BLACK = '#101418';
var RED = '#ff0000';
var HILITE = '#ffe766';
var SCALE = 80;
var squareSize = 120;
var origin = { x: 130, y: 500 };
var tVec = { dx: 260, dy: -210 };
var sVec = { dx: 300, dy: 130 };
var stage = 'single';
var currentStep = 0;
var dragMode = null;

var demoSteps = [
  {
    title: 'One translation',
    narration: 'Drag the red vector t. The orange square moves rigidly by exactly that displacement, and the homogeneous matrix changes only in the entries tₓ and tᵧ.',
    state: { compositionStage: 'single' }
  },
  {
    title: 'Apply a second translation',
    narration: 'Add a second vector s from the translated square. The first square moves by t, then the intermediate result moves again by s to reach the final square.',
    state: { compositionStage: 'chained' }
  },
  {
    title: 'Collapse the chain',
    narration: 'The direct red arrow from the original square to the final square is t+s. The matrix product T(s)T(t) has translation entries tₓ+sₓ and tᵧ+sᵧ, matching the single direct displacement.',
    state: { compositionStage: 'composed' }
  }
];

var axisMarker = draw.marker(18, 18, function (add) {
  add.path('M 0 0 L 18 9 L 0 18 Z').fill(BLACK).stroke('none');
}).ref(17, 9).attr({ orient: 'auto', markerUnits: 'strokeWidth' });

var redMarker = draw.marker(18, 18, function (add) {
  add.path('M 0 0 L 18 9 L 0 18 Z').fill(RED).stroke('none');
}).ref(17, 9).attr({ orient: 'auto', markerUnits: 'strokeWidth' });

var squaresLayer = draw.group();
var axesLayer = draw.group();
var arrowsLayer = draw.group();
var labelLayer = draw.group();
var matrixLayer = draw.group();
var handleLayer = draw.group();

function makeSquare(name) {
  var g = squaresLayer.group().attr({ id: name });
  var r = g.rect(squareSize, squareSize)
    .fill(ORANGE)
    .stroke({ color: BLACK, width: 6, linejoin: 'miter' });
  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('A square is translated without rotating, scaling, or shearing.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Rigid translation', 'Every point of the orange square moves by the same displacement vector. Its size, orientation, and shape stay unchanged.');
    });
  return { group: g, rect: r };
}

var originalSq = makeSquare('originalSquare');
var interSq = makeSquare('translatedSquare');
var finalSq = makeSquare('finalSquare');

axesLayer.line(55, origin.y, 825, origin.y)
  .stroke({ color: BLACK, width: 7, linecap: 'butt' })
  .marker('end', axisMarker);
axesLayer.line(origin.x, 560, origin.x, 85)
  .stroke({ color: BLACK, width: 7, linecap: 'butt' })
  .marker('end', axisMarker);

function haloText(parent, str, x, y, size, italic) {
  return parent.text(str)
    .move(x, y)
    .font({ family: 'Times New Roman, serif', size: size, style: italic ? 'italic' : 'normal' })
    .fill(BLACK)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
}

haloText(axesLayer, 'x', 795, 516, 54, true);
haloText(axesLayer, 'y', 92, 20, 54, true);

var tArrow = arrowsLayer.line(0, 0, 0, 0)
  .stroke({ color: RED, width: 7, linecap: 'round' })
  .marker('end', redMarker);
var sArrow = arrowsLayer.line(0, 0, 0, 0)
  .stroke({ color: RED, width: 7, linecap: 'round' })
  .marker('end', redMarker);
var sumArrow = arrowsLayer.line(0, 0, 0, 0)
  .stroke({ color: RED, width: 7, linecap: 'round' })
  .marker('end', redMarker);

[tArrow, sArrow, sumArrow].forEach(function (el) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('A translation vector records the same displacement for every point.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Translation vector', 'The arrow gives the displacement applied to all points. In a composition, the direct displacement is found by adding the vector components.');
    });
});

var tHandle = handleLayer.circle(34).fill({ color: RED, opacity: 0.001 }).stroke('none').css('cursor', 'grab');
var sHandle = handleLayer.circle(34).fill({ color: RED, opacity: 0.001 }).stroke('none').css('cursor', 'grab');
tHandle.on('pointerdown', function (e) { beginDrag(e, 't'); });
sHandle.on('pointerdown', function (e) { beginDrag(e, 's'); });

function beginDrag(e, mode) {
  e.preventDefault();
  dragMode = mode;
  if (e.target && e.target.setPointerCapture) {
    try { e.target.setPointerCapture(e.pointerId); } catch (err) {}
  }
}

document.addEventListener('pointermove', function (e) {
  if (!dragMode) return;
  var p = svgPoint(e);
  if (dragMode === 't') {
    var tx = clamp(p.x, 80, 765);
    var ty = clamp(p.y, 90, 540);
    tVec.dx = tx - origin.x;
    tVec.dy = ty - origin.y;
  } else if (dragMode === 's') {
    var mid = intermediateCenter();
    var fx = clamp(p.x, 90, 790);
    var fy = clamp(p.y, 90, 540);
    sVec.dx = fx - mid.x;
    sVec.dy = fy - mid.y;
  }
  render();
});

document.addEventListener('pointerup', function () {
  dragMode = null;
});

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

function intermediateCenter() {
  return { x: origin.x + tVec.dx, y: origin.y + tVec.dy };
}

function finalCenter() {
  return { x: origin.x + tVec.dx + sVec.dx, y: origin.y + tVec.dy + sVec.dy };
}

function componentX(v) {
  return v.dx / SCALE;
}

function componentY(v) {
  return -v.dy / SCALE;
}

function fmt(n) {
  var z = Math.round(n * 10) / 10;
  return (Math.abs(z) < 0.05 ? 0 : z).toFixed(1);
}

function moveSquare(sq, c) {
  sq.rect.move(c.x - squareSize / 2, c.y - squareSize / 2);
}

function setLine(line, a, b) {
  line.plot(a.x, a.y, b.x, b.y);
}

function setVisible(el, on) {
  if (on) el.show(); else el.hide();
}

function drawReadout(text, x, y) {
  var t = haloText(labelLayer, text, x, y, 25, false).font({ family: 'Arial, sans-serif', size: 20 });
  t.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Coordinates are the x and y components of the displayed displacement vector.', e); })
    .on('mouseleave', function () { hideTooltip(); });
  return t;
}

function arrowLabel(str, x, y, size) {
  return haloText(labelLayer, str, x, y, size || 46, true);
}

function drawMatrix(x, y, label, entries, highlights, note) {
  var g = matrixLayer.group();
  var cellW = 54, cellH = 30, rows = 3, cols = 3;
  var labelText = g.text(label + ' =')
    .move(x, y + 30)
    .font({ family: 'Times New Roman, serif', size: 24, style: 'italic' })
    .fill(BLACK)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });

  var mx = x + labelText.bbox().width + 12;
  var my = y;
  g.rect(cols * cellW + 42, rows * cellH + 22)
    .move(mx - 18, my - 8)
    .fill({ color: '#fff', opacity: 0.86 })
    .stroke('none')
    .back();

  g.path('M ' + (mx - 8) + ' ' + my + ' L ' + (mx - 18) + ' ' + my + ' L ' + (mx - 18) + ' ' + (my + rows * cellH) + ' L ' + (mx - 8) + ' ' + (my + rows * cellH))
    .fill('none').stroke({ color: BLACK, width: 2.5 });
  g.path('M ' + (mx + cols * cellW + 8) + ' ' + my + ' L ' + (mx + cols * cellW + 18) + ' ' + my + ' L ' + (mx + cols * cellW + 18) + ' ' + (my + rows * cellH) + ' L ' + (mx + cols * cellW + 8) + ' ' + (my + rows * cellH))
    .fill('none').stroke({ color: BLACK, width: 2.5 });

  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      var key = r + ',' + c;
      if (highlights[key]) {
        g.rect(cellW - 8, cellH - 5)
          .move(mx + c * cellW + 4, my + r * cellH + 3)
          .fill({ color: HILITE, opacity: 0.9 })
          .stroke({ color: '#d2a400', width: 1 });
      }
      g.text(entries[r][c])
        .center(mx + c * cellW + cellW / 2, my + r * cellH + cellH / 2 + 1)
        .font({ family: 'Arial, sans-serif', size: 18 })
        .fill(BLACK);
    }
  }

  if (note) {
    g.text(note)
      .move(x, y + 104)
      .font({ family: 'Arial, sans-serif', size: 16 })
      .fill(BLACK)
      .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  }

  g.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('The highlighted rightmost column stores the translation entries.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Homogeneous translation matrix', 'The upper-left 2×2 block is the identity, so no rotation or scaling occurs. The highlighted translation column stores the displacement components.');
    });
  return g;
}

function renderMatrices() {
  matrixLayer.clear();
  var tx = fmt(componentX(tVec)), ty = fmt(componentY(tVec));
  var sx = fmt(componentX(sVec)), sy = fmt(componentY(sVec));
  var sumx = fmt(componentX({ dx: tVec.dx + sVec.dx, dy: 0 }));
  var sumy = fmt(componentY({ dx: 0, dy: tVec.dy + sVec.dy }));
  var hi = { '0,2': true, '1,2': true };

  if (stage === 'single') {
    drawMatrix(505, 48, 'T(t)', [['1', '0', tx], ['0', '1', ty], ['0', '0', '1']], hi, "p′ = T(t)p");
  } else if (stage === 'chained') {
    drawMatrix(470, 34, 'T(t)', [['1', '0', tx], ['0', '1', ty], ['0', '0', '1']], hi, '');
    drawMatrix(470, 170, 'T(s)', [['1', '0', sx], ['0', '1', sy], ['0', '0', '1']], hi, '');
  } else {
    drawMatrix(412, 46, 'T(s)T(t)', [['1', '0', 'tₓ+sₓ'], ['0', '1', 'tᵧ+sᵧ'], ['0', '0', '1']], hi, 'translation column = (' + sumx + ', ' + sumy + ')');
  }
}

function renderLabels() {
  labelLayer.clear();
  var mid = intermediateCenter();
  var fin = finalCenter();

  var tMid = { x: (origin.x + mid.x) / 2, y: (origin.y + mid.y) / 2 };
  arrowLabel('t', tMid.x - 52, tMid.y - 18, 48);

  drawReadout('t = (' + fmt(componentX(tVec)) + ', ' + fmt(componentY(tVec)) + ')', 250, 540);

  if (stage === 'chained' || stage === 'composed') {
    var sMid = { x: (mid.x + fin.x) / 2, y: (mid.y + fin.y) / 2 };
    arrowLabel('s', sMid.x - 5, sMid.y - 54, 48);
    drawReadout('s = (' + fmt(componentX(sVec)) + ', ' + fmt(componentY(sVec)) + ')', 475, 540);
  }

  if (stage === 'composed') {
    var directMid = { x: (origin.x + fin.x) / 2, y: (origin.y + fin.y) / 2 };
    arrowLabel('t+s', directMid.x + 35, directMid.y - 8, 44);
    drawReadout('t+s = (' + fmt((tVec.dx + sVec.dx) / SCALE) + ', ' + fmt(-(tVec.dy + sVec.dy) / SCALE) + ')', 645, 540);
  }
}

function render() {
  var mid = intermediateCenter();
  var fin = finalCenter();

  moveSquare(originalSq, origin);
  moveSquare(interSq, mid);
  moveSquare(finalSq, fin);

  setLine(tArrow, origin, mid);
  setLine(sArrow, mid, fin);
  setLine(sumArrow, origin, fin);

  tHandle.center(mid.x, mid.y);
  sHandle.center(fin.x, fin.y);

  if (stage === 'single') {
    setVisible(interSq.group, true);
    setVisible(finalSq.group, false);
    setVisible(tArrow, true);
    setVisible(sArrow, false);
    setVisible(sumArrow, false);
    setVisible(tHandle, true);
    setVisible(sHandle, false);
    tArrow.opacity(1);
  } else if (stage === 'chained') {
    setVisible(interSq.group, true);
    setVisible(finalSq.group, true);
    setVisible(tArrow, true);
    setVisible(sArrow, true);
    setVisible(sumArrow, false);
    setVisible(tHandle, true);
    setVisible(sHandle, true);
    tArrow.opacity(1);
    sArrow.opacity(1);
  } else {
    setVisible(interSq.group, true);
    setVisible(finalSq.group, true);
    setVisible(tArrow, true);
    setVisible(sArrow, true);
    setVisible(sumArrow, true);
    setVisible(tHandle, true);
    setVisible(sHandle, true);
    tArrow.opacity(0.38);
    sArrow.opacity(0.38);
    sumArrow.opacity(1);
  }

  renderLabels();
  renderMatrices();
}

function updateStageButtons() {
  var ids = {
    single: 'stageSingleBtn',
    chained: 'stageChainedBtn',
    composed: 'stageComposedBtn'
  };
  Object.keys(ids).forEach(function (k) {
    var b = document.getElementById(ids[k]);
    if (b) {
      if (k === stage) b.classList.add('active'); else b.classList.remove('active');
    }
  });
}

function setCompositionStage(next) {
  stage = next;
  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.compositionStage === next) currentStep = i;
  }
  applyStepUI();
  render();
}

function applyStepUI() {
  var step = demoSteps[currentStep];
  stage = step.state.compositionStage;
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
