// @FIGURE_CODE_BEGIN
var W = 1600, H = 520;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var ORANGE = '#ff8000';
var BLACK = '#101418';
var RED = '#ff0000';
var SEP = '#e7e7e7';
var SQ = 132;

var leftOrigin = { x: 70, y: 455 };
var rightOrigin = { x: 1030, y: 455 };
var t1 = { dx: 275, dy: -205 };
var t2 = { dx: 230, dy: 115 };
var currentStep = 0;
var viewMode = 'Two-panel textbook view';
var dragTarget = null;

var demoSteps = [
  {
    title: 'Textbook layout',
    narration: 'The default view shows the source-style two-panel figure: one translation on the left and a pair of composed translations on the right.',
    state: { viewMode: 'Two-panel textbook view' }
  },
  {
    title: 'One translation',
    narration: 'Focus on the left panel: the orange square is copied to a new position by the red vector t, with its size and orientation unchanged.',
    state: { viewMode: 'Focus: single translation' }
  },
  {
    title: 'Composed translations',
    narration: 'Focus on the right panel: translating first by t₁ and then by t₂ reaches the same final square as one direct translation by t₁ + t₂.',
    state: { viewMode: 'Focus: composition' }
  }
];

var redMarker = draw.marker(24, 18, function (add) {
  add.path('M 1 1 L 22 9 L 1 17 L 6 9 Z').fill(RED).stroke('none');
}).ref(22, 9).attr({ orient: 'auto', markerUnits: 'userSpaceOnUse' });

var axisMarker = draw.marker(42, 42, function (add) {
  add.path('M 0 0 L 42 21 L 0 42 L 10 21 Z').fill(BLACK).stroke('none');
}).ref(41, 21).attr({ orient: 'auto', markerUnits: 'userSpaceOnUse' });

var squareLayer = draw.group();
var axesLayer = draw.group();
var arrowLayer = draw.group();
var labelLayer = draw.group();
var handleLayer = draw.group();

draw.line(800, 44, 800, 506).stroke({ color: SEP, width: 2, opacity: 0.55 });

function makeSquare(cx, cy) {
  var r = squareLayer.rect(SQ, SQ)
    .move(cx - SQ / 2, cy - SQ / 2)
    .fill(ORANGE)
    .stroke({ color: BLACK, width: 5, linejoin: 'miter' });
  r.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('A translation moves every point by the same vector; the square does not rotate or resize.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Rigid translation', 'The orange square is shifted as a whole. Its side lengths and orientation stay exactly the same.');
    });
  return r;
}

function drawAxes(origin, xEnd, yTop, xLab, yLab) {
  axesLayer.line(origin.x - 42, origin.y, xEnd, origin.y)
    .stroke({ color: BLACK, width: 5, linecap: 'butt' })
    .marker('end', axisMarker);
  axesLayer.line(origin.x, H + 2, origin.x, yTop)
    .stroke({ color: BLACK, width: 5, linecap: 'butt' })
    .marker('end', axisMarker);
  axesLayer.text('x')
    .move(xLab.x, xLab.y)
    .font({ family: 'Times New Roman, serif', size: 44, style: 'italic' })
    .fill(BLACK);
