drawAxes(leftOrigin, 765, 50, { x: 724, y: 466 }, { x: 30, y: 8 });
drawAxes(rightOrigin, 1585, 50, { x: 1538, y: 466 }, { x: 990, y: 8 });

var leftOriginal = makeSquare(leftOrigin.x, leftOrigin.y);
var leftTranslated = makeSquare(leftOrigin.x + t1.dx, leftOrigin.y + t1.dy);
var rightOriginal = makeSquare(rightOrigin.x, rightOrigin.y);
var rightIntermediate = makeSquare(rightOrigin.x + t1.dx, rightOrigin.y + t1.dy);
var rightFinal = makeSquare(rightOrigin.x + t1.dx + t2.dx, rightOrigin.y + t1.dy + t2.dy);

function makeArrow() {
  var l = arrowLayer.line(0, 0, 1, 1)
    .stroke({ color: RED, width: 4, linecap: 'round', linejoin: 'round' })
    .marker('end', redMarker);
  l.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Translation vectors are placed tip-to-tail; the direct displacement is their vector sum.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Vector sum', 'Doing one translation after another is equivalent to one translation by the sum of the displacement vectors.');
    });
  return l;
}

var leftTArrow = makeArrow();
var rightT1Arrow = makeArrow();
var rightT2Arrow = makeArrow();
var rightSumArrow = makeArrow();

function makeHandle(kind) {
  var c = handleLayer.circle(42).fill({ color: RED, opacity: 0.001 }).stroke('none').css('cursor', 'grab');
  c.on('pointerdown', function (e) {
