userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Translation composition</span>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;line-height:1.35;max-width:260px"></span>
<span style="display:flex;align-items:center;gap:6px"><button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button></span>
<label>View <select id="viewModeInput" onchange="update_viewMode(this.value)"><option>Two-panel textbook view</option><option>Focus: single translation</option><option>Focus: composition</option></select></label>
<span style="font-size:10px;line-height:1.35;color:#333">Drag the red arrow tips. The orange squares translate without rotating or resizing.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 1900, H = 820;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var ORANGE = '#ff8000';
var BLACK = '#101418';
var RED = '#ff0000';
var SQ = 170;

var leftOrigin = { x: 145, y: 735 };
var rightOrigin = { x: 1050, y: 735 };
var tVec = { dx: 430, dy: -330 };
var sVec = { dx: 290, dy: 190 };
var currentStep = 0;
var viewMode = 'Two-panel textbook view';
var dragTarget = null;

var demoSteps = [
  {
    title: 'Textbook layout',
    narration: 'The default view shows the source-style two-panel figure: a single translation on the left and a composed pair of translations on the right.',
    state: { viewMode: 'Two-panel textbook view' }
  },
  {
    title: 'One translation',
    narration: 'Focus on the left panel: the orange square is copied to a new position by the red vector t, with its size and orientation unchanged.',
    state: { viewMode: 'Focus: single translation' }
  },
  {
    title: 'Composed translations',
    narration: 'Focus on the right panel: translating first by t and then by s reaches the same final square as one direct translation by t+s.',
    state: { viewMode: 'Focus: composition' }
  }
];

var redMarker = draw.marker(68, 50, function (add) {
  add.path('M 2 2 L 66 25 L 2 48 L 16 25 Z').fill(RED).stroke('none');
}).ref(63, 25).attr({ orient: 'auto', markerUnits: 'userSpaceOnUse' });

var axisMarker = draw.marker(54, 54, function (add) {
  add.path('M 0 0 L 54 27 L 0 54 L 13 27 Z').fill(BLACK).stroke('none');
}).ref(53, 27).attr({ orient: 'auto', markerUnits: 'userSpaceOnUse' });

var squareLayer = draw.group();
var axesLayer = draw.group();
var arrowLayer = draw.group();
var labelLayer = draw.group();
var handleLayer = draw.group();

function makeSquare(cx, cy) {
  var r = squareLayer.rect(SQ, SQ)
    .move(cx - SQ / 2, cy - SQ / 2)
    .fill(ORANGE)
    .stroke({ color: BLACK, width: 8, linejoin: 'miter' });
  r.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('A translation shifts every point by the same vector; the square keeps its size and orientation.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Rigid translation', 'The orange square is moved as a whole. Its side lengths, angles, and orientation do not change.');
    });
  return r;
}

function drawAxes(origin, xEnd, yTop, xLab, yLab) {
  axesLayer.line(origin.x - 95, origin.y, xEnd, origin.y)
    .stroke({ color: BLACK, width: 8, linecap: 'butt' })
    .marker('end', axisMarker);
  axesLayer.line(origin.x, H + 12, origin.x, yTop)
    .stroke({ color: BLACK, width: 8, linecap: 'butt' })
    .marker('end', axisMarker);
  axesLayer.text('x')
    .move(xLab.x, xLab.y)
    .font({ family: 'Times New Roman, serif', size: 82, style: 'italic' })
    .fill(BLACK);
  axesLayer.text('y')
    .move(yLab.x, yLab.y)
    .font({ family: 'Times New Roman, serif', size: 82, style: 'italic' })
    .fill(BLACK);
}

var leftOriginal = makeSquare(leftOrigin.x, leftOrigin.y);
var leftTranslated = makeSquare(leftOrigin.x + tVec.dx, leftOrigin.y + tVec.dy);
var rightOriginal = makeSquare(rightOrigin.x, rightOrigin.y);
var rightIntermediate = makeSquare(rightOrigin.x + tVec.dx, rightOrigin.y + tVec.dy);
var rightFinal = makeSquare(rightOrigin.x + tVec.dx + sVec.dx, rightOrigin.y + tVec.dy + sVec.dy);

drawAxes(leftOrigin, 870, 85, { x: 820, y: 735 }, { x: 58, y: 18 });
drawAxes(rightOrigin, 1875, 85, { x: 1823, y: 735 }, { x: 962, y: 18 });

function makeArrow() {
  var l = arrowLayer.line(0, 0, 1, 1)
    .stroke({ color: RED, width: 8, linecap: 'round', linejoin: 'round' })
    .marker('end', redMarker);
  l.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Translation vectors can be placed tip-to-tail; the direct displacement is their vector sum.', e);
    })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Vector sum', 'Doing two translations successively is equivalent to one translation by the sum of the two displacement vectors.');
    });
  return l;
}

var leftTArrow = makeArrow();
var rightTArrow = makeArrow();
var rightSArrow = makeArrow();
var rightSumArrow = makeArrow();

function makeHandle(kind) {
  var c = handleLayer.circle(86)
    .fill({ color: RED, opacity: 0.001 })
    .stroke('none')
    .css('cursor', 'grab');
  c.on('pointerdown', function (e) {
    e.preventDefault();
    dragTarget = kind;
    c.css('cursor', 'grabbing');
    try { c.node.setPointerCapture(e.pointerId); } catch (err) {}
  });
  c.on('mousemove', function (e) { showTooltip('Drag this arrow tip to change the translation vector.', e); })
    .on('mouseleave', function () { hideTooltip(); });
  return c;
}

var leftTHandle = makeHandle('leftT');
var rightTHandle = makeHandle('rightT');
var rightSHandle = makeHandle('rightS');

function labelText(str, x, y, size) {
  return labelLayer.text(str)
    .move(x, y)
    .font({ family: 'Times New Roman, serif', size: size, style: 'italic' })
    .fill(BLACK)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 7, 'stroke-linejoin': 'round' });
}

function setSquareCenter(rect, p) {
  rect.move(p.x - SQ / 2, p.y - SQ / 2);
}

function plotLine(line, a, b) {
  line.plot(a.x, a.y, b.x, b.y);
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function normalizeVectors() {
  tVec.dx = clamp(tVec.dx, 320, 520);
  tVec.dy = clamp(tVec.dy, -430, -250);

  var midX = rightOrigin.x + tVec.dx;
  var midY = rightOrigin.y + tVec.dy;
  sVec.dx = clamp(sVec.dx, 190, 1850 - midX);
  sVec.dy = clamp(sVec.dy, 115, 315);

  var finalY = rightOrigin.y + tVec.dy + sVec.dy;
  if (finalY > 725) sVec.dy -= (finalY - 725);
}

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

document.addEventListener('pointermove', function (e) {
  if (!dragTarget) return;
  var p = svgPoint(e);
  if (dragTarget === 'leftT') {
    tVec.dx = p.x - leftOrigin.x;
    tVec.dy = p.y - leftOrigin.y;
  } else if (dragTarget === 'rightT') {
    tVec.dx = p.x - rightOrigin.x;
    tVec.dy = p.y - rightOrigin.y;
  } else if (dragTarget === 'rightS') {
    sVec.dx = p.x - (rightOrigin.x + tVec.dx);
    sVec.dy = p.y - (rightOrigin.y + tVec.dy);
  }
  normalizeVectors();
  render();
});

document.addEventListener('pointerup', function () {
  dragTarget = null;
  leftTHandle.css('cursor', 'grab');
  rightTHandle.css('cursor', 'grab');
  rightSHandle.css('cursor', 'grab');
});

function renderLabels() {
  labelLayer.clear();

  var leftTip = { x: leftOrigin.x + tVec.dx, y: leftOrigin.y + tVec.dy };
  var leftMid = { x: (leftOrigin.x + leftTip.x) / 2, y: (leftOrigin.y + leftTip.y) / 2 };
  labelText('t', leftMid.x + 74, leftMid.y - 18, 78);

  var rMid = { x: rightOrigin.x + tVec.dx, y: rightOrigin.y + tVec.dy };
  var rFin = { x: rMid.x + sVec.dx, y: rMid.y + sVec.dy };
  var tMid = { x: (rightOrigin.x + rMid.x) / 2, y: (rightOrigin.y + rMid.y) / 2 };
  var sMid = { x: (rMid.x + rFin.x) / 2, y: (rMid.y + rFin.y) / 2 };
  var sumMid = { x: (rightOrigin.x + rFin.x) / 2, y: (rightOrigin.y + rFin.y) / 2 };

  labelText('t', tMid.x + 48, tMid.y - 8, 78);
  labelText('s', sMid.x + 24, sMid.y - 48, 78);
  labelText('t+s', sumMid.x + 230, sumMid.y - 8, 78);
}

function render() {
  normalizeVectors();

  var leftTip = { x: leftOrigin.x + tVec.dx, y: leftOrigin.y + tVec.dy };
  var rMid = { x: rightOrigin.x + tVec.dx, y: rightOrigin.y + tVec.dy };
  var rFin = { x: rMid.x + sVec.dx, y: rMid.y + sVec.dy };

  setSquareCenter(leftOriginal, leftOrigin);
  setSquareCenter(leftTranslated, leftTip);
  setSquareCenter(rightOriginal, rightOrigin);
  setSquareCenter(rightIntermediate, rMid);
  setSquareCenter(rightFinal, rFin);

  plotLine(leftTArrow, leftOrigin, leftTip);
  plotLine(rightTArrow, rightOrigin, rMid);
  plotLine(rightSArrow, rMid, rFin);
  plotLine(rightSumArrow, rightOrigin, rFin);

  leftTHandle.center(leftTip.x, leftTip.y);
  rightTHandle.center(rMid.x, rMid.y);
  rightSHandle.center(rFin.x, rFin.y);

  renderLabels();
}

function applyViewBox() {
  if (viewMode === 'Focus: single translation') {
    draw.viewbox(0, 0, 900, 820);
  } else if (viewMode === 'Focus: composition') {
    draw.viewbox(900, 0, 1000, 820);
  } else {
    draw.viewbox(0, 0, W, H);
  }
}

function updateStepText() {
  var n = document.getElementById('demoNarration');
  var l = document.getElementById('stepLabel');
  if (n) n.textContent = demoSteps[currentStep].narration;
  if (l) l.textContent = (currentStep + 1) + ' / ' + demoSteps.length + ': ' + demoSteps[currentStep].title;
}

function update_viewMode(v) {
  viewMode = v;
  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.viewMode === v) currentStep = i;
  }
  var sel = document.getElementById('viewModeInput');
  if (sel) sel.value = viewMode;
  updateStepText();
  applyViewBox();
}

function applyStep() {
  viewMode = demoSteps[currentStep].state.viewMode;
  var sel = document.getElementById('viewModeInput');
  if (sel) sel.value = viewMode;
  updateStepText();
  applyViewBox();
}

function nextStep() {
  currentStep = (currentStep + 1) % demoSteps.length;
  applyStep();
}

function prevStep() {
  currentStep = (currentStep + demoSteps.length - 1) % demoSteps.length;
  applyStep();
}

window.nextStep = nextStep;
window.prevStep = prevStep;
window.update_viewMode = update_viewMode;

render();
applyStep();
window.__markRendered();
// @FIGURE_CODE_END

